"""
Test script to reproduce the admin.E108 issue with fields 
accessible only via instance (like PositionField).
"""
import django
from django.conf import settings

# Configure minimal Django settings
if not settings.configured:
    settings.configure(
        DEBUG=True,
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'django.contrib.contenttypes',
            'django.contrib.auth',
            'django.contrib.admin',
        ],
        USE_TZ=True,
    )
    django.setup()

from django.contrib import admin
from django.contrib.admin.checks import ModelAdminChecks
from django.db import models


# Create a custom descriptor that raises an error when accessed on the class
# This simulates PositionField's behavior
class PositionFieldDescriptor:
    """A descriptor that only works on instances, not on the class."""
    def __get__(self, instance, cls):
        if instance is None:
            # When accessed on class (not instance), raise an error
            raise AttributeError("PositionField cannot be accessed via class")
        return instance.__dict__.get('_position', 0)

    def __set__(self, instance, value):
        instance.__dict__['_position'] = value


class PositionField(models.IntegerField):
    """A field that can only be accessed on instances."""
    def contribute_to_class(self, cls, name, **kwargs):
        super().contribute_to_class(cls, name, **kwargs)
        setattr(cls, name, PositionFieldDescriptor())


# Define a model with our custom field
class Thing(models.Model):
    number = models.IntegerField(default=0)
    order = PositionField()

    class Meta:
        app_label = 'test_app'


# Define a ModelAdmin with list_display including the PositionField
@admin.register(Thing)
class ThingAdmin(admin.ModelAdmin):
    list_display = ['number', 'order']


# Run the check
checker = ModelAdminChecks()
errors = checker._check_list_display_item(ThingAdmin, 'order', 'list_display[1]')

if errors:
    print("ERRORS found (this is the bug):")
    for error in errors:
        print(f"  - {error.id}: {error.msg}")
else:
    print("No errors found (this is expected)")

# Also verify that invalid fields still produce errors
errors2 = checker._check_list_display_item(ThingAdmin, 'no_such_field', 'list_display[1]')
if errors2:
    print("\nCorrectly detected invalid field 'no_such_field':")
    for error in errors2:
        print(f"  - {error.id}: {error.msg}")
else:
    print("\nERROR: Failed to detect invalid field 'no_such_field'!")
EOF
