                            obj=obj.__class__,
                            id='admin.E108',
                        )
                    ]
            if isinstance(field, models.ManyToManyField):
                return [
                    checks.Error(
                        "The value of '%s' must not be a ManyToManyField." % label,
                        obj=obj.__class__,
                        id='admin.E109',
                    )
                ]
            return []'''

new_content = content.replace(old_func, new_func)

if content == new_content:
    print("ERROR: Replacement not made!")
else:
    with open('/testbed/django/contrib/admin/checks.py', 'w') as f:
        f.write(new_content)
    print("Fix applied successfully!")
